import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Configuring fields","description":"Label form fields, mark them required, prefill them, and hide them.","frontmatter":{"title":"Configuring fields","description":"Label form fields, mark them required, prefill them, and hide them."},"headers":[],"relativePath":"en/formulare/felder-konfigurieren.md","filePath":"en/formulare/felder-konfigurieren.md","lastUpdated":1787319236000}'),o={name:"en/formulare/felder-konfigurieren.md"};function l(r,e,d,s,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="configuring-fields" tabindex="-1">Configuring fields <a class="header-anchor" href="#configuring-fields" aria-label="Permalink to &quot;Configuring fields&quot;">​</a></h1><p>Every field in a form can be configured individually. Clicking <strong>Edit</strong> on a field opens its <strong>Field settings</strong>.</p><h2 id="label-and-help-text" tabindex="-1">Label and help text <a class="header-anchor" href="#label-and-help-text" aria-label="Permalink to &quot;Label and help text&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Label</strong></td><td>Caption shown in the form</td></tr><tr><td><strong>Description</strong></td><td>Explanatory text below the label</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The label only applies to this form</p><p>The column name on the Grid stays unchanged. So internally it can be called <code>customer_status</code> while the form asks <em>How satisfied are you?</em></p><p>Use this: internal field names are often meaningless to the people filling out the form.</p></div><h2 id="required-field" tabindex="-1">Required field <a class="header-anchor" href="#required-field" aria-label="Permalink to &quot;Required field&quot;">​</a></h2><p><strong>Required field</strong> prevents submission while the field is empty. The message reads <em>Please fill in this required field.</em></p><div class="warning custom-block"><p class="custom-block-title">Use sparingly</p><p>Every required field raises the abandonment rate. Ask yourself for each one: can I really not process this without that piece of information?</p><p>On multi-page forms, required fields belong near the front — if someone abandons the form, you at least have the most important data.</p></div><h2 id="input-behavior" tabindex="-1">Input behavior <a class="header-anchor" href="#input-behavior" aria-label="Permalink to &quot;Input behavior&quot;">​</a></h2><h3 id="multi-line" tabindex="-1">Multi-line <a class="header-anchor" href="#multi-line" aria-label="Permalink to &quot;Multi-line&quot;">​</a></h3><p>For text fields: several lines instead of one. For comments, descriptions, and notes.</p><h3 id="component-type" tabindex="-1">Component type <a class="header-anchor" href="#component-type" aria-label="Permalink to &quot;Component type&quot;">​</a></h3><p>Determines how the field is displayed:</p><table tabindex="0"><thead><tr><th>Column type</th><th>Options</th></tr></thead><tbody><tr><td>Single select, Multiple select</td><td><em>Dropdown menu</em> or <em>List</em></td></tr><tr><td>Files</td><td><em>Choose file</em> or <em>Record video</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Dropdown or list?</p><p><strong>List</strong> shows all options at once — good for up to about five options, and when the choice should be made deliberately.</p><p><strong>Dropdown menu</strong> saves space — better with many options and on mobile devices.</p></div><h3 id="allow-adding-files-only" tabindex="-1">Allow adding files only <a class="header-anchor" href="#allow-adding-files-only" aria-label="Permalink to &quot;Allow adding files only&quot;">​</a></h3><p>For file fields: people filling out the form can add attachments but can&#39;t delete existing ones.</p><div class="tip custom-block"><p class="custom-block-title">Important for editing forms</p><p>When a form edits an <strong>existing</strong> entry, this setting prevents already-uploaded documents from being accidentally removed.</p></div><h3 id="enable-barcode-scanner" tabindex="-1">Enable barcode scanner <a class="header-anchor" href="#enable-barcode-scanner" aria-label="Permalink to &quot;Enable barcode scanner&quot;">​</a></h3><p>Allows filling the field via camera — for item numbers, serial numbers, inventory tags.</p><h2 id="prefilling-and-hiding" tabindex="-1">Prefilling and hiding <a class="header-anchor" href="#prefilling-and-hiding" aria-label="Permalink to &quot;Prefilling and hiding&quot;">​</a></h2><p>Three settings that are best thought of together:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Prefilled</strong></td><td>A default value is already in the field when it opens</td></tr><tr><td><strong>Not editable</strong></td><td>The field is shown but can&#39;t be edited</td></tr><tr><td><strong>Not visible</strong></td><td>The field is not shown but is still submitted</td></tr></tbody></table><h3 id="typical-combinations" tabindex="-1">Typical combinations <a class="header-anchor" href="#typical-combinations" aria-label="Permalink to &quot;Typical combinations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Goal</th><th>Settings</th></tr></thead><tbody><tr><td>Record origin without anyone seeing it</td><td><em>Not visible</em> + value via <a href="/en/formulare/vorausgefuellte-links">prefilled link</a></td></tr><tr><td>Show context but keep it fixed</td><td><em>Prefilled</em> + <em>Not editable</em></td></tr><tr><td>Suggest a value, allow changes</td><td><em>Prefilled</em> only</td></tr><tr><td>Show existing data without editing</td><td><em>Not editable</em></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">&quot;Not visible&quot; is not confidential</p><p>The field is only hidden in the interface — nothing more. With a prefilled link, the value even sits in the address and is readable by anyone who has the link.</p><p>Don&#39;t put personal or confidential data there.</p></div><h2 id="plan-dependent-settings" tabindex="-1">Plan-dependent settings <a class="header-anchor" href="#plan-dependent-settings" aria-label="Permalink to &quot;Plan-dependent settings&quot;">​</a></h2><p>Four settings aren&#39;t available on every plan:</p><ul><li><strong>Not editable</strong></li><li><strong>Not visible</strong></li><li><strong>Prefilled</strong></li><li><strong>Enable barcode scanner</strong></li></ul><div class="warning custom-block"><p class="custom-block-title">A downgrade can remove settings</p><p>If a Space moves to a lower plan, ApptiveGrid removes paid form settings. Check your forms after a plan change.</p></div><h2 id="removing-a-field" tabindex="-1">Removing a field <a class="header-anchor" href="#removing-a-field" aria-label="Permalink to &quot;Removing a field&quot;">​</a></h2><p>Via <strong>Remove</strong> in the field settings. This takes the field out of the <strong>form</strong> — the column on the Grid and its data remain untouched.</p><h2 id="which-fields-can-t-be-collected" tabindex="-1">Which fields can&#39;t be collected <a class="header-anchor" href="#which-fields-can-t-be-collected" aria-label="Permalink to &quot;Which fields can&#39;t be collected&quot;">​</a></h2><p>Four column types have no form field:</p><table tabindex="0"><thead><tr><th>Type</th><th>Reason</th></tr></thead><tbody><tr><td><strong>Rich Text</strong></td><td>no input field defined</td></tr><tr><td><strong>Use linked value</strong></td><td>calculated</td></tr><tr><td><strong>Calculate sum</strong></td><td>calculated</td></tr><tr><td><strong>Formula</strong></td><td>calculated</td></tr></tbody></table><p>For longer text, use <strong>Text</strong> with the <em>Multi-line</em> setting instead.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>ApptiveGrid checks input based on the column type. The messages are listed under <a href="/en/fehlerbehebung/haeufige-fehlermeldungen">Common error messages</a> — for example <em>Only numbers (0-9) are allowed</em> or <em>An international dialing code is required (e.g. +49)</em>.</p><div class="tip custom-block"><p class="custom-block-title">Mention expected formats in the description</p><p>For phone numbers, dates, and coordinates, you&#39;ll avoid input errors if the field description includes an example.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/formulare/formular-erstellen">Creating a form</a></li><li><a href="/en/formulare/gestaltung">Design</a></li><li><a href="/en/formulare/vorausgefuellte-links">Prefilled links</a></li></ul>',41)])])}const p=t(o,[["render",l]]);export{m as __pageData,p as default};
